# Lesson 1 - sections 5 (properties) and 6 (order of operations)
from lib import *

K5, K51, K52, K6 = '5. លក្ខណៈនៃប្រមាណវិធី', '5.1. លក្ខណៈនៃវិធីបូក', '5.2. លក្ខណៈនៃវិធីគុណ', '6. លំដាប់នៃប្រមាណវិធីលើចំនួនគត់'


def gat(x, y, r, c, cell=26, color=BLUE, gap=4, split=None, colors=None):
    W, H, b = grid(r, c, cell, color, gap, split, colors)
    return f'<g transform="translate({x},{y})">{b}</g>', W, H


def blocks(n, color, x, y, s=44, gap=6):
    return ''.join(rect(x + i * (s + gap), y, s, s, color, 8) for i in range(n))


def build():
    S = []
    S.append(part(5, 'លក្ខណៈនៃប្រមាណវិធី', fig(svg(1000, 120, T(500, 80, 'a + b = b + a  ·  a × b = b × a  ·  a(b + c) = ab + ac', 44, TEAL), '16vh'))))

    # ---------- 5.1 addition
    v = blocks(4, BLUE, 40, 20) + blocks(5, GREEN, 40 + 4 * 50, 20) + T(520, 150, '4 + 5 = 9', 38, NAVY) + blocks(5, GREEN, 40, 190) + blocks(4, BLUE, 40 + 5 * 50, 190) + T(520, 320, '5 + 4 = 9', 38, NAVY)
    S.append(ex(K51, 'ឧទាហរណ៍ 1', p('គេដឹងថា ' + m('4+5=9') + ' និង ' + m('5+4=9') + ' ។ ដូច្នេះ ' + m('4+5=5+4=9') + ' ។') + fig(svg(700, 340, v, '30vh'), 'ដូរទីតាំង · ចំនួនសរុបដដែល') + p('គេឃើញថាលំដាប់នៃការបូកពីរចំនួនមិនប្រែប្រួលលទ្ធផលទេ។ ក្នុងករណីនេះ៖ គេថា វិធីបូកមានលក្ខណៈ ' + hl('ត្រឡប់', RED) + ' ។')))
    g1 = blocks(2, BLUE, 40, 40) + blocks(3, GREEN, 40 + 2 * 50, 40) + blocks(5, ORANGE, 40 + 5 * 50, 40) + f'<path d="M36 28 h98 M136 28 h148" stroke="{NAVY}" stroke-width="4" fill="none"/>' + T(520, 150, '(2 + 3) + 5 = 5 + 5 = 10', 36, NAVY, 'start').replace('x="520"', 'x="40"') + blocks(2, BLUE, 40, 220) + blocks(3, GREEN, 40 + 2 * 50, 220) + blocks(5, ORANGE, 40 + 5 * 50, 220) + T(40, 345, '2 + (3 + 5) = 2 + 8 = 10', 36, NAVY, 'start')
    S.append(ex(K51, 'ឧទាហរណ៍ 2', p('គេដឹងថា ' + m('2+3+5=(2+3)+5=5+5=10') + ' ម្យ៉ាងទៀត ' + m('2+3+5=2+(3+5)=2+8=10')) + fig(svg(700, 370, g1, '30vh'), 'ដាក់វង់ក្រចកផ្សេងគ្នា · ផលបូកដដែល') + p('ដូច្នេះ ' + m('2+3+5=(2+3)+5=2+(3+5)')) + p('គេឃើញថាលំដាប់នៃការផ្តុំពីរចំនួនមិនប្រែប្រួលលទ្ធផលទេ ។ ក្នុងករណីនេះ គេថា វិធីបូកមានលក្ខណៈ ' + hl('ផ្តុំ', RED) + ' ។')))
    S.append(ex(K51, 'ឧទាហរណ៍', p('គេដឹងថា ' + m('1+0=1') + ' និង ' + m('0+1=1')) + p('ដូច្នេះ៖ ' + m('1+0=0+1=1') + ' ចំនួន ' + m('0') + ' ហៅថា ' + hl('ធាតុណឺតចំពោះវិធីបូក', RED) + ' ។') + fig(svg(700, 110, blocks(1, BLUE, 40, 30) + T(150, 70, '+', 40, NAVY) + rect(190, 30, 44, 44, '#fff', 8, GREY, 3) + T(212, 62, '0', 30, GREY) + T(300, 70, '=', 40, NAVY) + blocks(1, BLUE, 340, 30), '14vh'), 'បូក 0 មិនប្រែប្រួលអ្វីទេ')))
    S.append(key(K51, 'ជាទូទៅ', p('ចំពោះគ្រប់ចំនួនគត់ ' + m('a, b') + ' និង ' + m('c')) + ol([m('a+b=b+a'), m('a+(b+c)=(a+b)+c'), m('a+0=0+a=a') + ', ' + m('0') + ' ជាធាតុណឺតចំពោះវិធីបូក ។'])))

    # ---------- 5.2 multiplication
    a, W1, H1 = gat(30, 30, 5, 7, 34)
    b2, W2, H2 = gat(430, 30, 7, 5, 34, ORANGE)
    S.append(ex(K52, 'ឧទាហរណ៍ 1', p('រូបទី 1 : ' + m('7\\times 5=35') + ' និងរូបទី 2 : ' + m('5\\times 7=35') + ' ។') + fig(svg(780, 345, a + b2 + T(165, 255, '7 × 5 = 35', 32, BLUE) + T(527, 335, '5 × 7 = 35', 32, ORANGE), '32vh'), 'តារាងដូចគ្នា តែបង្វិល · ចំនួនក្រឡាស្មើគ្នា') + p('ដូច្នេះ ' + m('7\\times 5=5\\times 7=35') + ' ។ គេថា វិធីគុណមានលក្ខណៈ ' + hl('ត្រឡប់', RED) + ' ។')))
    g_a, wa, ha = gat(20, 30, 3, 4, 28)
    g_b = ''.join(gat(250 + k * 100, 20, 3, 4, 17, BLUE, 3)[0] for k in range(5))
    g_c = ''.join(gat(20 + k * 120, 190, 3, 5, 17, ORANGE, 3)[0] for k in range(4))
    S.append(ex(K52, 'ឧទាហរណ៍ 2', p('រូបទី 1: ' + m('3\\times 4') + ' រូបទី 2: ' + m('5\\times (3\\times 4)') + ' និងរូបទី 3: ' + m('4\\times (3\\times 5)')) + fig(svg(780, 290, g_a + T(75, 150, '3 × 4', 28, BLUE) + g_b + T(450, 122, '5 ក្រុមនៃ 3 × 4', 26, BLUE) + g_c + T(240, 283, '4 ក្រុមនៃ 3 × 5', 26, ORANGE), '32vh')) + p('រូបទី 2: ' + m('5\\times (3\\times 4)=5\\times 12=60') + ' · រូបទី 3: ' + m('4\\times (3\\times 5)=4\\times 15=60')) + p('ដូច្នេះ៖ វិធីគុណមានលក្ខណៈ ' + hl('ផ្តុំ', RED) + ' ។')))
    gd, w1d, h1d = gat(30, 30, 6, 7, 32, BLUE, 4, 3, [BLUE, ORANGE])
    S.append(ex(K52, 'ឧទាហរណ៍ 3', p('តាមរូបបង្ហាញថា ' + m('6\\times (3+4)=(6\\times 3)+(6\\times 4)') + ' និង ' + m('(3+4)\\times 6=(3\\times 6)+(4\\times 6)') + ' ។') + fig(svg(420, 300, gd + T(30 + 3 * 36 / 2 + 2, 282, '6×3', 26, BLUE) + T(30 + 3 * 36 + 4 * 36 / 2, 282, '6×4', 26, ORANGE), '32vh'), 'តារាង 6 × 7 បំបែកជាពីរ៖ 6×3 (ខៀវ) និង 6×4 (ទឹកក្រូច)') + p('គេឃើញថា វិធីគុណមានលក្ខណៈ ' + hl('បំបែកចំពោះវិធីបូក', RED) + ' ។')))
    S.append(ex(K52, 'ឧទាហរណ៍ 4', p('គេដឹងថា ' + m('1\\times 14=14') + ' និង ' + m('14\\times 1=14') + ' ។') + p('ចំនួន ' + m('1') + ' ហៅថា ' + hl('ធាតុណឺតចំពោះវិធីគុណ', RED) + ' ។') + fig(svg(700, 100, T(350, 68, '1 × 14 = 14 × 1 = 14', 46, TEAL), '12vh'))))
    S.append(key(K52, 'ជាទូទៅ', p('ចំពោះគ្រប់ចំនួនគត់ ' + m('a, b') + ' និង ' + m('c')) + ol([m('a\\times b=b\\times a'), m('a\\times (b\\times c)=(a\\times b)\\times c'), m('a(b+c)=(a\\times b)+(a\\times c)'), m('a\\times 1=1\\times a=a') + ', ' + m('1') + ' ជាធាតុណឺតចំពោះវិធីគុណ ។'])))
    S.append(prac(K52, 'លំហាត់គំរូ', p('ចានមួយមានកូនឃ្លីច្រើនជាង ' + m('80') + ' គ្រាប់ ប៉ុន្តែតិចជាង ' + m('90') + ' គ្រាប់ ហើយវាស្មើនិង ' + m('7') + ' ដងនៃផលបូកតួលេខនៃចំនួនឃ្លីទាំងអស់ ។ តើកូនឃ្លីសរុបដែលនៅក្នុងចានមានចំនួនប៉ុន្មានគ្រាប់?') + '<div class="fig"><div class="mb-wrap" data-widget="marbles"></div><div class="cap">ជ្រើសចំនួនមួយ រួចចុច ▶ ដើម្បីឱ្យកូនឃ្លីរត់លេងក្នុងចាន</div></div>'))
    rows = ''.join(f'<tr><td>{m("n="+str(n))}</td><td>{m("("+str(s[0])+"+"+str(s[1])+")\\times 7="+str(v))}</td><td>{ok}</td></tr>' for n, s, v, ok in [(81, (8, 1), 63, '<span class="no">✗ ' + m('63<80') + '</span>'), (82, (8, 2), 70, '<span class="no">✗ ' + m('70<80') + '</span>'), (83, (8, 3), 77, '<span class="no">✗ ' + m('77<80') + '</span>'), (84, (8, 4), 84, '<span class="ok">✓ ' + m('84=84') + '</span>'), (85, (8, 5), 91, '<span class="no">✗ ' + m('91>90') + '</span>')])
    S.append(sol(K52, 'ដំណោះស្រាយ', p('តាង ' + m('n') + ' ជាចំនួនគ្រាប់ឃ្លីទាំងអស់ដែល ' + m('80<n<90')) + f'<table class="tbl"><tr><th>ឃ្លី</th><th>7 × (ផលបូកតួលេខ)</th><th>ផ្ទៀងផ្ទាត់?</th></tr>{rows}</table>' + p('ដូច្នេះនៅក្នុងចានមានឃ្លីទាំងអស់ចំនួន ' + hl(m('84'), GREEN) + ' គ្រាប់ ។')))
    S.append(prac(K52, 'ប្រតិបត្តិ', p('គេដាក់ផ្លែក្រូចក្នុងកេសធំបី ដែលក្នុងមួយកេសផ្ទុកក្រូច ' + m('98') + ' ផ្លែ និងដាក់ក្នុងកេសតូចពីរដែលក្នុងមួយកេសផ្ទុកផ្លែក្រូច ' + m('24') + ' ផ្លែ ។ តើក្រូចសរុបមានប៉ុន្មានផ្លែ?') + fig(svg(900, 150, ''.join(rect(20 + i * 190, 20, 170, 110, ORANGE, 14) + T(105 + i * 190, 88, '98', 44, '#fff') for i in range(3)) + ''.join(rect(610 + i * 140, 50, 120, 80, '#ffc078', 14) + T(670 + i * 140, 102, '24', 36, NAVY) for i in range(2)), '20vh'), 'កេសធំ 3 · កេសតូច 2')))
    S.append(sol(K52, 'ចម្លើយ', p('រកចំនួនផ្លែក្រូចសរុបទាំងអស់ ៖') + ul(['ចំនួនផ្លែក្រូចនៅក្នុងកេសធំទាំង ' + m('3') + ' គឺ ៖ ' + m('3 \\times 98 = 294 \\text{ ផ្លែ}'), 'ចំនួនផ្លែក្រូចនៅក្នុងកេសតូចទាំង ' + m('2') + ' គឺ ៖ ' + m('2 \\times 24 = 48 \\text{ ផ្លែ}'), 'ចំនួនផ្លែក្រូចសរុបទាំងអស់មាន ៖ ' + m('294 + 48 = 342 \\text{ ផ្លែ}')]) + p('(ឬអាចសរសេរជាកន្សោមប្រមាណវិធីរួម ៖ ' + m('3 \\times 98 + 2 \\times 24 = 294 + 48 = 342 \\text{ ផ្លែ}') + ') ។') + p('ដូចនេះ ផ្លែក្រូចសរុបមានចំនួន ' + hl(m('342'), GREEN) + ' ផ្លែ ។')))

    # ---------- 6 order of operations
    ladder = svg(1000, 190, rect(20, 14, 300, 160, GREEN, 22) + T(170, 80, '១', 44, '#fff') + T(170, 134, '( ) និង [ ]', 36, '#fff') + rect(350, 14, 300, 160, ORANGE, 22) + T(500, 80, '២', 44, '#fff') + T(500, 134, '× និង ÷', 40, '#fff') + rect(680, 14, 300, 160, BLUE, 22) + T(830, 80, '៣', 44, '#fff') + T(830, 134, '+ និង −', 40, '#fff') + arrow(322, 94, 346, 94, NAVY, 5) + arrow(652, 94, 676, 94, NAVY, 5), '24vh')
    S.append(part(6, 'លំដាប់នៃប្រមាណវិធីលើចំនួនគត់', fig(ladder, 'ធ្វើតាមលំដាប់ ១ → ២ → ៣ · ក្នុងលំដាប់ដូចគ្នា ធ្វើពីឆ្វេងទៅស្តាំ')))
    S.append(ex(K6, 'ឧទាហរណ៍ 1', p('គណនា ' + m('19-3+7') + ' ។') + p('បើគេធ្វើវិធីបូកមុន គេបាន ' + m('19-3+7=19-(3+7)=19-10=9') + ' ' + '<span class="no">✗</span>') + p('បើគេធ្វើវិធីដកមុន គេបាន ' + m('19-3+7=(19-3)+7=16+7=23') + ' ' + '<span class="ok">✓</span>') + p('ដូច្នេះគេឃើញថា ' + m('19-(3+7)\\ne (19-3)+7') + ' ។') + p('គេត្រូវមានវិធានមួយច្បាស់លាស់ ក្នុងការធ្វើប្រមាណវិធីដែលមានតែវិធីបូកនិងដកគឺ ' + m('19-3+7=16+7=23') + ' ដែលជាវិធានត្រឹមត្រូវ ។')))
    S.append(ex(K6, 'ឧទាហរណ៍ 2', p('គណនា ' + m('12-2+10-14') + ' ។') + p('គេបាន ' + m('12-2+10-14 = 10+10-14 = 20-14=6')) + fig(svg(900, 120, T(60, 70, '12 − 2', 40, BLUE, 'start') + arrow(250, 60, 300, 60, NAVY, 4) + T(320, 70, '10 + 10', 40, GREEN, 'start') + arrow(520, 60, 570, 60, NAVY, 4) + T(590, 70, '20 − 14', 40, ORANGE, 'start') + arrow(770, 60, 810, 60, NAVY, 4) + T(830, 70, '6', 46, RED, 'start'), '14vh'), 'ពីឆ្វេងទៅស្តាំ')))
    S.append(key(K6, 'ជាទូទៅ', p('បើកន្សោមមានតែវិធីបូកនិងដក គេត្រូវធ្វើប្រមាណវិធីពីឆ្វេងទៅស្តាំ ។')))
    S.append(ex(K6, 'ឧទាហរណ៍ 3', p('គណនា ' + m('6\\times 12\\div 4') + ' ។ គេបាន ' + m('6\\times 12\\div 4=72\\div 4=18') + ' ។')))
    S.append(ex(K6, 'ឧទាហរណ៍ 4', p('គណនា ' + m('125\\div 5\\times 15') + ' ។ គេបាន ' + m('125\\div 5\\times 15=25\\times 15=375') + ' ។')))
    S.append(key(K6, 'ជាទូទៅ', p('បើកន្សោមមានតែវិធីគុណនិងចែក គេត្រូវធ្វើប្រមាណវិធីពីឆ្វេងទៅស្តាំ ។')))
    S.append(ex(K6, 'ឧទាហរណ៍ 5', p('គណនា ' + m('52-4\\times 12+18\\div 6\\times 3') + ' ។') + p('គេបាន ' + m('52-\\underline{4\\times 12}+\\underline{18\\div 6\\times 3}=\\underline{52-48}+\\underline{3\\times 3}=4+9=13') + ' ។') + fig(ladder, '១) × ÷ មុន (គូសបន្ទាត់ក្រោម) · ២) បូក ដក ពីឆ្វេងទៅស្តាំ')))
    S.append(key(K6, 'ជាទូទៅ', p('បើកន្សោមមួយមានប្រមាណវិធីទាំងបួន គេត្រូវធ្វើប្រមាណវិធីគុណ ឬប្រមាណវិធីចែកមុនប្រមាណវិធីបូក ដក ពីឆ្វេងទៅស្តាំ ។')))
    S.append(ex(K6, 'ឧទាហរណ៍ 6', p('គណនា ' + m('12-(4\\times 3-2)+9') + ' ។') + p('គេបាន ' + m('12-(4\\times 3-2)+9=12-(12-2)+9=12-10+9=2+9=11') + ' ។')))
